              <div>
                <p className="text-sm font-semibold text-[#121212]">Analytics</p>
                <p className="text-xs text-[#696969] mt-0.5 leading-relaxed">
                  Helps us understand how visitors interact with our website.
                </p>
              </div>
            </div>
            <button
              type="button"
              role="switch"
              aria-checked={analytics}
