          >
            Manage Preferences
          </button>
          <button
            onClick={handleDismiss}
            className="p-2.5 text-[#696969] hover:text-[#121212] rounded-lg hover:bg-[#F5F5F5] transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-[#EB0028] focus:ring-offset-2"
            aria-label="Dismiss cookie banner"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Main App                                                           */
/* ------------------------------------------------------------------ */

export default function App() {
  const [preferencesOpen, setPreferencesOpen] = useState(false);

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Main content */}
